import { useMemo, useState } from "react";

type Marker = { at: number; label: string; tone?: "info" | "warn" | "error" };

export function TimelineRuler({
  start,
  end,
  markers = [],
}: {
  start: number;
  end: number;
  markers?: Marker[];
}) {
  const [cursor, setCursor] = useState((start + end) / 2);

  const ticks = useMemo(() => {
    const span = end - start;
    const steps = 10;
    return Array.from({ length: steps + 1 }, (_, i) => ({
      at: start + (span * i) / steps,
      major: i % 5 === 0,
    }));
  }, [start, end]);

  const toPercent = (value: number) =>
    Math.min(100, Math.max(0, ((value - start) / (end - start)) * 100));

  const onScrub = (event: React.PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    setCursor(start + ((event.clientX - box.left) / box.width) * (end - start));
  };

  return (
    <div className="tlr-root">
      <div
        className="tlr-track"
        role="slider"
        tabIndex={0}
        aria-label="Timeline position"
        aria-valuemin={start}
        aria-valuemax={end}
        aria-valuenow={Math.round(cursor)}
        onPointerDown={onScrub}
        onPointerMove={(e) => e.buttons === 1 && onScrub(e)}
        onKeyDown={(e) => {
          if (e.key === "ArrowLeft") setCursor((c) => Math.max(start, c - 1));
          if (e.key === "ArrowRight") setCursor((c) => Math.min(end, c + 1));
        }}
      >
        {ticks.map((tick) => (
          <span
            key={tick.at}
            className={tick.major ? "tlr-tick is-major" : "tlr-tick"}
            style={{ left: toPercent(tick.at) + "%" }}
          />
        ))}

        {markers.map((marker) => (
          <i
            key={marker.label}
            className="tlr-marker"
            data-tone={marker.tone ?? "info"}
            style={{ left: toPercent(marker.at) + "%" }}
            title={marker.label}
          />
        ))}

        <div className="tlr-cursor" style={{ left: toPercent(cursor) + "%" }}>
          <span className="tlr-readout">{Math.round(cursor)}</span>
        </div>
      </div>

      <div className="tlr-labels">
        {ticks.map((tick) =>
          tick.major ? (
            <span key={tick.at} style={{ left: toPercent(tick.at) + "%" }}>
              {Math.round(tick.at)}
            </span>
          ) : null,
        )}
      </div>
    </div>
  );
}

cssRules:
.tlr-root {
  position: relative;
  padding: 24px 0 28px;
  background: var(--surface-inset, #0c0e13);
  border-radius: 8px;
  border: 1px solid var(--line-subtle, #1e2230);
  --tone-info: #38bdf8;
  --tone-warn: #fbbf24;
  --tone-error: #f87171;
}
.tlr-track {
  position: relative;
  height: 34px;
  margin: 0 16px;
  cursor: crosshair;
  outline: none;
}
.tlr-track:focus-visible {
  box-shadow: 0 0 0 2px var(--accent, #6366f1);
  border-radius: 4px;
}
.tlr-tick {
  position: absolute;
  bottom: 0;
  width: 1px;
  height: 6px;
  background: var(--line-strong, #334155);
}
.tlr-tick.is-major {
  height: 16px;
  background: var(--text-muted, #64748b);
}
.tlr-marker {
  position: absolute;
  top: 0;
  width: 8px;
  height: 8px;
  margin-left: -4px;
  border-radius: 2px;
  background: var(--tone-info);
}
.tlr-marker[data-tone='warn'] { background: var(--tone-warn); }
.tlr-marker[data-tone='error'] { background: var(--tone-error); }
.tlr-cursor {
  position: absolute;
  top: 18px;
  bottom: -8px;
  width: 2px;
  margin-left: -1px;
  background: var(--accent, #e2e8f0);
  pointer-events: none;
}
.tlr-readout {
  position: absolute;
  top: -22px;
  left: 50%;
  transform: translateX(-50%);
  padding: 1px 5px;
  font-family: ui-monospace, monospace;
  font-size: 10px;
  border-radius: 3px;
  background: var(--surface-raised, #1b2130);
  color: var(--text-strong, #f8fafc);
  white-space: nowrap;
}
.tlr-labels {
  position: relative;
  height: 14px;
  margin: 0 16px;
}
.tlr-labels span {
  position: absolute;
  transform: translateX(-50%);
  font-family: ui-monospace, monospace;
  font-size: 10px;
  color: var(--text-muted, #64748b);
}
